for(const p of HEAVEN_PROFILES){if(encFind(p.id))throw Error('Duplicate Heaven Gardens identity');PLANT_CALENDAR[p.id]=p.calendar;ENC_PLANTS.push({...p,look:p.look,bloom:gardenMonths(p.calendar.bloom)});}PLANT_SUPPLIERS.push(...HEAVEN_PRODUCTS);
function heavenFactsHTML(r){if(!r.catalogFacts)return '';const labels={height:'Височина по каталога',light:'Светлина по каталога',water:'Влажност по каталога',soil:'Почва по каталога',bloom:'Цъфтеж по каталога',cold:'Зимоустойчивост по каталога — непотвърдена за обекта'};return '<details><summary>Данни от партньора</summary>'+Object.entries(labels).filter(([k])=>r.catalogFacts[k]).map(([k,l])=>'<p><strong>'+l+':</strong> '+esc(r.catalogFacts[k])+'</p>').join('')+'<p class="muted">Работен ориентир от доставчика. При противоречие потвърди по етикета; не използвай каталожна температура като гаранция за София.</p></details>';}
const originalSupplierCard=supplierCard;supplierCard=function(r){const h=originalSupplierCard(r);return r.shop==='Heaven Gardens'?h.replace('</section>',heavenFactsHTML(r)+'</section>'):h;};
// Unknown catalogue fields remain unknown in calculation and calendar screens.
const heavenCalendarBase=gardenCalendarHTML;gardenCalendarHTML=function(p){const h=heavenCalendarBase(p);return p.group==='heaven-gardens'?h.replace('null cm · коригирай по сорт','Не е уточнено — въведи след проверка на сорта'):h;};
const heavenConditionsBase=gardenConditions;gardenConditions=function(ids){if(ids.some(id=>{const p=encFind(id);return p?.group==='heaven-gardens'&&(encLight(p).includes('Не е уточнено')||encWater(p)==='Не е уточнено')}))throw Error('За част от избраните растения няма потвърдена светлина или вода. Уточни условията преди автоматично сравнение.');return heavenConditionsBase(ids);};
const heavenCompatibilityBase=gpCompatibility;gpCompatibility=function(plants,z){const result=heavenCompatibilityBase(plants,z);for(const r of plants){const p=encFind(r.plantId);if(p?.group==='heaven-gardens')result.push(p.name+': работен каталожен профил — провери вида, зрелия размер, въведеното разстояние и местното зимуване.');}return result;};
